SourceCode.Declaration:
public final class TFMPageLookupContent
{
    TFMPagesTmpLookup mobTmpPages;
    FormGridControl gridControl;
    FormGroupControl splitterControl;
    FormGroupControl previewControl;
    FormStringControl strControlPageID;
    FormStringControl strControlPageType;
    TFMHtmlViewerCtrl formViewerControl;

}

Method.Source:
public void new(FormGroupControl _contentGroup, TFMPagesTmpLookup _mobTmpPages, boolean _showPageType)
{
    mobTmpPages = _mobTmpPages;

    gridControl = _contentGroup.addControl(FormControlType::Grid, 'gridControl');
    gridControl.visibleRows(8, AutoMode::Fixed);
    gridControl.multiSelect(false);
    gridControl.dataSource(_contentGroup.dataSource());

    strControlPageID = gridControl.addControl(FormControlType::String, 'TFMPagesTmpLookup_PageID');
    strControlPageID.label("@SYS7426");
    strControlPageID.dataField(fieldNum(TFMPagesTmpLookup, PageID));
    strControlPageID.dataSource(_contentGroup.dataSource());

    if(_showPageType)
    {
        strControlPageType = gridControl.addControl(FormControlType::String, 'TFMPagesTmpLookup_PageType');
        strControlPageType.label("@SYS342003");
        strControlPageType.dataField(fieldNum(TFMPagesTmpLookup, PageType));
    }

    strControlPageType = gridControl.addControl(FormControlType::String, 'TFMPagesTmpLookup_Title');
    strControlPageType.label("@SYS98533");
    strControlPageType.dataField(fieldNum(TFMPagesTmpLookup, Title));

    strControlPageType.dataSource(_contentGroup.dataSource());

    splitterControl = _contentGroup.addControl(FormControlType::Group, 'splitterControl');

    previewControl = _contentGroup.addControl(FormControlType::Group, 'previewControl');
    previewControl.skip(true);
    previewControl.widthMode(FormWidth::Manual);
    previewControl.width(230);
    previewControl.heightMode(FormHeight ::SizeToAvailable);

    formViewerControl = previewControl.addControlEx(classStr(TFMHtmlViewerCtrl), 'htmlViewer');
    formViewerControl.widthMode(FormWidth::Manual);
    formViewerControl.width(201);
    formViewerControl.heightMode(FormHeight::SizeToAvailable);
}
